//! wineapps — declarative Wine app manager.
//!
//! Consumes the registry generated by `modules/system/wine-apps.nix`
//! (`/etc/wineapps/apps.json` by default; override with `WINEAPPS_REGISTRY`) and
//! manages per-app Wine prefixes under `$XDG_DATA_HOME/wineprefixes` (default
//! `~/.local/share/wineprefixes`; override with `WINEPREFIX_BASE`).
//!
//! Commands:
//!   wineapps list                  show declared apps + install status
//!   wineapps install [APP...]      ensure apps are installed (no args: all)
//!   wineapps sync [APP...]         alias for install
//!   wineapps uninstall APP...      remove app prefixes
//!   wineapps run APP [ARGS...]     launch the app's main executable
//!   wineapps prefix APP            print the app's prefix directory
//!   wineapps status                wine/winetricks/prefix overview
//!
//! Rust port of the previous Python script: the registry is a small JSON
//! document (read by the compact parser at the bottom of this file) and every
//! Wine operation is a call to the binaries the package wrapper puts on `PATH`
//! — wine, wineboot, wineserver and winetricks — so the client itself carries
//! no Wine knowledge and no crates.

use std::collections::BTreeMap;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

const REGISTRY_DEFAULT: &str = "/etc/wineapps/apps.json";

// -- environment -------------------------------------------------------

fn env_or(name: &str, fallback: &str) -> String {
    match std::env::var(name) {
        Ok(value) if !value.is_empty() => value,
        _ => fallback.to_string(),
    }
}

fn expand_user(path: &str) -> PathBuf {
    if let Some(rest) = path.strip_prefix("~/") {
        if let Some(home) = std::env::var_os("HOME") {
            return PathBuf::from(home).join(rest);
        }
    }
    PathBuf::from(path)
}

pub fn registry_path() -> PathBuf {
    expand_user(&env_or("WINEAPPS_REGISTRY", REGISTRY_DEFAULT))
}

/// `WINEPREFIX_BASE`, else `$XDG_DATA_HOME/wineprefixes`, else
/// `~/.local/share/wineprefixes`.
pub fn prefix_root() -> PathBuf {
    if let Ok(value) = std::env::var("WINEPREFIX_BASE") {
        if !value.is_empty() {
            return expand_user(&value);
        }
    }
    let data_home = match std::env::var("XDG_DATA_HOME") {
        Ok(value) if !value.is_empty() => expand_user(&value),
        _ => expand_user("~/.local/share"),
    };
    data_home.join("wineprefixes")
}

// -- registry ----------------------------------------------------------

/// One declared app from the registry.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct App {
    pub name: String,
    pub prefix: String,
    pub arch: String,
    pub executable: Option<String>,
    pub installer: Option<String>,
    pub install_args: String,
    pub comment: String,
    pub winetricks: Vec<String>,
}

/// Load the registry; a missing file is an empty registry, like the Python
/// loader.
pub fn load_registry_from(path: &Path) -> Result<BTreeMap<String, App>, String> {
    if !path.exists() {
        return Ok(BTreeMap::new());
    }
    let text = std::fs::read_to_string(path)
        .map_err(|exc| format!("cannot read {}: {exc}", path.display()))?;
    let document =
        json::parse(&text).ok_or_else(|| format!("{}: not a JSON document", path.display()))?;
    let mut apps = BTreeMap::new();
    if let json::Value::Object(entries) = document {
        for (name, value) in entries {
            let json::Value::Object(_) = value else {
                continue;
            };
            let field = |key: &str| {
                value
                    .get(key)
                    .and_then(json::Value::as_str)
                    .map(str::to_string)
            };
            let winetricks = value
                .get("winetricks")
                .and_then(json::Value::as_array)
                .map(|items| {
                    items
                        .iter()
                        .filter_map(|item| item.as_str().map(str::to_string))
                        .collect()
                })
                .unwrap_or_default();
            apps.insert(
                name.clone(),
                App {
                    name: field("name").unwrap_or(name),
                    prefix: field("prefix").unwrap_or_default(),
                    arch: field("arch").unwrap_or_else(|| "win64".to_string()),
                    executable: field("executable").filter(|value| !value.is_empty()),
                    installer: field("installer").filter(|value| !value.is_empty()),
                    install_args: field("installArgs").unwrap_or_default(),
                    comment: field("comment").unwrap_or_default(),
                    winetricks,
                },
            );
        }
    }
    Ok(apps)
}

pub fn load_registry() -> Result<BTreeMap<String, App>, String> {
    load_registry_from(&registry_path())
}

pub fn app_prefix(app: &App) -> PathBuf {
    prefix_root().join(&app.prefix)
}

pub fn resolve_exe(app: &App, prefix: &Path) -> Option<PathBuf> {
    app.executable.as_ref().map(|exe| prefix.join(exe))
}

/// A prefix counts as installed when the marker exists or the executable does.
pub fn is_installed(_app: &App, prefix: &Path, exe: Option<&Path>) -> bool {
    if prefix.join(".wineapps-installed").exists() {
        return true;
    }
    exe.is_some_and(|exe| exe.exists())
}

/// Environment for one app's prefix: `WINEPREFIX`, `WINEARCH` and the wine
/// directory prepended to `PATH`.
pub fn wine_env(prefix: &Path, app: Option<&App>) -> Vec<(String, String)> {
    let mut env: Vec<(String, String)> = std::env::vars().collect();
    set_var(&mut env, "WINEPREFIX", &prefix.display().to_string());
    if let Some(app) = app {
        set_var(&mut env, "WINEARCH", &app.arch);
    }
    if let Ok(wine) = std::env::var("WINE") {
        if !wine.is_empty() {
            let wine_dir = Path::new(&wine)
                .parent()
                .map(|parent| parent.display().to_string())
                .unwrap_or_default();
            let path = format!("{wine_dir}:{}", env_or("PATH", ""));
            set_var(&mut env, "PATH", &path);
        }
    }
    env
}

fn set_var(env: &mut Vec<(String, String)>, key: &str, value: &str) {
    if let Some(entry) = env.iter_mut().find(|(name, _)| name == key) {
        entry.1 = value.to_string();
    } else {
        env.push((key.to_string(), value.to_string()));
    }
}

fn run(argv: &[String], env: &[(String, String)]) -> i32 {
    eprintln!("+ {}", argv.join(" "));
    let mut command = Command::new(&argv[0]);
    command.args(&argv[1..]);
    for (key, value) in env {
        command.env(key, value);
    }
    match command.status() {
        Ok(status) => status.code().unwrap_or(-1),
        Err(exc) => {
            eprintln!("error: cannot run {}: {exc}", argv[0]);
            -1
        }
    }
}

/// Wait until every wine process in this prefix has exited (installer spawned
/// children included). Installers terminate on their own.
fn wait_wine(env: &[(String, String)]) {
    let wineserver = env_or("WINESERVER", "wineserver");
    let _ = Command::new(wineserver)
        .arg("-w")
        .envs(env.iter().map(|(key, value)| (key, value)))
        .stdout(Stdio::null())
        .stderr(Stdio::null())
        .status();
}

/// Local path of an installer, downloading `http(s)://` URLs into the cache.
///
/// The download goes through `curl` instead of an in-process HTTP client: the
/// installers are large, redirect through CDNs and are served over TLS, which
/// keeps the client itself free of a TLS stack.
pub fn fetch_installer(installer: &str, name: &str) -> Option<PathBuf> {
    if installer.starts_with("http://") || installer.starts_with("https://") {
        let cache_home = env_or("XDG_CACHE_HOME", &format!("{}/.cache", env_or("HOME", "")));
        let cache = expand_user(&cache_home).join("wineapps");
        if std::fs::create_dir_all(&cache).is_err() {
            eprintln!("error: cannot create {}", cache.display());
            return None;
        }
        let file_name = Path::new(installer)
            .file_name()
            .map(|name| name.to_string_lossy().to_string())
            .unwrap_or_else(|| "installer".to_string());
        let dest = cache.join(format!("{name}-{file_name}"));
        if !dest.exists() {
            println!("{name}: downloading {installer}");
            let status = Command::new("curl")
                .args(["-fL", "--retry", "2", "-o"])
                .arg(&dest)
                .arg(installer)
                .status();
            match status {
                Ok(status) if status.success() => {}
                Ok(status) => {
                    eprintln!("error: download failed: curl exited with {status}");
                    let _ = std::fs::remove_file(&dest);
                    return None;
                }
                Err(exc) => {
                    eprintln!("error: download failed: {exc}");
                    return None;
                }
            }
        }
        return Some(dest);
    }
    let path = expand_user(installer);
    if !path.exists() {
        eprintln!("error: installer not found: {}", path.display());
        return None;
    }
    Some(path)
}

/// Ensure one app is installed; `true` when it ends up installed.
pub fn install_one(app: &App) -> bool {
    let prefix = app_prefix(app);
    let exe = resolve_exe(app, &prefix);
    if is_installed(app, &prefix, exe.as_deref()) {
        println!("{}: already installed ({})", app.name, prefix.display());
        return true;
    }
    if let Err(exc) = std::fs::create_dir_all(&prefix) {
        eprintln!("error: cannot create {}: {exc}", prefix.display());
        return false;
    }
    let env = wine_env(&prefix, Some(app));

    println!(
        "{}: initializing prefix {} ({})",
        app.name,
        prefix.display(),
        app.arch
    );
    let wineboot = env_or("WINEBOOT", "wineboot");
    if run(&[wineboot, "-u".to_string()], &env) != 0 {
        eprintln!("error: wineboot failed for {}", app.name);
        return false;
    }
    wait_wine(&env);

    for verb in &app.winetricks {
        println!("{}: winetricks {verb}", app.name);
        let winetricks = env_or("WINETRICKS", "winetricks");
        let argv = vec![winetricks, "-q".to_string(), verb.clone()];
        if run(&argv, &env) != 0 {
            eprintln!("error: winetricks {verb} failed for {}", app.name);
            return false;
        }
        wait_wine(&env);
    }

    if let Some(installer) = &app.installer {
        let Some(local) = fetch_installer(installer, &app.name) else {
            return false;
        };
        let wine = env_or("WINE", "wine");
        let mut argv: Vec<String> = Vec::new();
        let local_text = local.display().to_string();
        if local_text.to_lowercase().ends_with(".msi") {
            argv.extend([wine, "msiexec".to_string(), "/i".to_string(), local_text]);
        } else {
            argv.extend([wine, local_text]);
        }
        argv.extend(install_args(&app.install_args));
        println!("{}: running installer {}", app.name, local.display());
        if run(&argv, &env) != 0 {
            eprintln!("error: installer failed for {}", app.name);
            return false;
        }
        wait_wine(&env);
    }

    let marker = prefix.join(".wineapps-installed");
    if let Err(exc) = std::fs::write(&marker, format!("{}\n", app.name)) {
        eprintln!("error: cannot write {}: {exc}", marker.display());
        return false;
    }
    println!("{}: installed ({})", app.name, prefix.display());
    true
}

/// `shlex.split` for the installer arguments.
fn install_args(text: &str) -> Vec<String> {
    let mut words = Vec::new();
    let mut current = String::new();
    let mut quote: Option<char> = None;
    for ch in text.chars() {
        match quote {
            Some(q) => {
                if ch == q {
                    quote = None;
                } else {
                    current.push(ch);
                }
            }
            None if ch == '\'' || ch == '"' => quote = Some(ch),
            None if ch.is_whitespace() => {
                if !current.is_empty() {
                    words.push(std::mem::take(&mut current));
                }
            }
            None => current.push(ch),
        }
    }
    if !current.is_empty() {
        words.push(current);
    }
    words
}

// -- commands ----------------------------------------------------------

/// `list` distinguishes a declared-but-manual app from a missing installer;
/// `status` collapses both into `missing`, like the Python client did.
fn state_of(app: &App, prefix: &Path, detailed: bool) -> &'static str {
    let exe = resolve_exe(app, prefix);
    if is_installed(app, prefix, exe.as_deref()) {
        "installed"
    } else if detailed && app.installer.is_none() {
        "manual"
    } else {
        "missing"
    }
}

fn cmd_list() -> i32 {
    let apps = match load_registry() {
        Ok(apps) => apps,
        Err(exc) => {
            eprintln!("error: {exc}");
            return 1;
        }
    };
    if apps.is_empty() {
        println!("no apps declared (features.wine.apps is empty)");
        return 0;
    }
    for (name, app) in &apps {
        let prefix = app_prefix(app);
        println!(
            "{name}\t{}\t{}\t{}\t{}",
            state_of(app, &prefix, true),
            app.prefix,
            app.arch,
            app.comment
        );
    }
    0
}

fn cmd_install(names: &[String]) -> i32 {
    let apps = match load_registry() {
        Ok(apps) => apps,
        Err(exc) => {
            eprintln!("error: {exc}");
            return 1;
        }
    };
    if apps.is_empty() {
        eprintln!("error: no apps declared (features.wine.apps is empty)");
        return 1;
    }
    let selected: Vec<&String> = if names.is_empty() {
        apps.keys().collect()
    } else {
        names.iter().collect()
    };
    let mut code = 0;
    for name in selected {
        let Some(app) = apps.get(name) else {
            eprintln!("error: unknown app {name}");
            code = 1;
            continue;
        };
        if !install_one(app) {
            code = 1;
        }
    }
    code
}

fn cmd_uninstall(names: &[String]) -> i32 {
    let apps = match load_registry() {
        Ok(apps) => apps,
        Err(exc) => {
            eprintln!("error: {exc}");
            return 1;
        }
    };
    let mut code = 0;
    for name in names {
        let Some(app) = apps.get(name) else {
            eprintln!("error: unknown app {name}");
            code = 1;
            continue;
        };
        let prefix = app_prefix(app);
        if !prefix.exists() {
            println!("{name}: no prefix at {}", prefix.display());
            continue;
        }
        if app.prefix != *name {
            eprintln!(
                "error: {name} uses shared prefix '{}'; remove it manually",
                app.prefix
            );
            code = 1;
            continue;
        }
        println!("{name}: removing prefix {}", prefix.display());
        if let Err(exc) = std::fs::remove_dir_all(&prefix) {
            eprintln!("error: cannot remove {}: {exc}", prefix.display());
            code = 1;
        }
    }
    code
}

fn cmd_run(name: &str, rest: &[String]) -> i32 {
    let apps = match load_registry() {
        Ok(apps) => apps,
        Err(exc) => {
            eprintln!("error: {exc}");
            return 1;
        }
    };
    let Some(app) = apps.get(name) else {
        eprintln!("error: unknown app {name}");
        return 1;
    };
    if app.executable.is_none() {
        eprintln!("error: {name} has no 'executable' configured");
        return 1;
    }
    let prefix = app_prefix(app);
    let exe = resolve_exe(app, &prefix);
    let Some(exe) = exe.clone().filter(|path| path.exists()) else {
        eprintln!(
            "error: executable not found: {}",
            exe.map(|path| path.display().to_string())
                .unwrap_or_default()
        );
        return 1;
    };
    let env = wine_env(&prefix, None);
    let wine = env_or("WINE", "wine");
    // Detach from the caller: GUI apps live as long as the user keeps them
    // open, so the CLI must not hold stdout/stderr (a waiting pipe would hang
    // any script that launched the app).
    let mut command = Command::new(wine);
    command
        .arg(&exe)
        .args(rest)
        .envs(env.iter().map(|(key, value)| (key, value)))
        .current_dir(&prefix)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::null());
    match command.spawn() {
        Ok(_) => {
            println!("{name}: launched {}", exe.display());
            0
        }
        Err(exc) => {
            eprintln!("error: cannot launch {}: {exc}", exe.display());
            1
        }
    }
}

fn cmd_prefix(name: &str) -> i32 {
    let apps = match load_registry() {
        Ok(apps) => apps,
        Err(exc) => {
            eprintln!("error: {exc}");
            return 1;
        }
    };
    let Some(app) = apps.get(name) else {
        eprintln!("error: unknown app {name}");
        return 1;
    };
    println!("{}", app_prefix(app).display());
    0
}

fn which(program: &str) -> Option<PathBuf> {
    if program.contains('/') {
        let path = PathBuf::from(program);
        return path.is_file().then_some(path);
    }
    let path = std::env::var_os("PATH")?;
    std::env::split_paths(&path)
        .map(|dir| dir.join(program))
        .find(|candidate| candidate.is_file())
}

fn cmd_status() -> i32 {
    let wine = match std::env::var("WINE") {
        Ok(value) if !value.is_empty() => Some(value),
        _ => which("wine").map(|path| path.display().to_string()),
    };
    let winetricks = match std::env::var("WINETRICKS") {
        Ok(value) if !value.is_empty() => Some(value),
        _ => which("winetricks").map(|path| path.display().to_string()),
    };
    println!("wine: {}", wine.unwrap_or_else(|| "not found".to_string()));
    println!(
        "winetricks: {}",
        winetricks.unwrap_or_else(|| "not found".to_string())
    );
    println!("prefix root: {}", prefix_root().display());
    let apps = match load_registry() {
        Ok(apps) => apps,
        Err(exc) => {
            eprintln!("error: {exc}");
            return 1;
        }
    };
    println!("declared apps: {}", apps.len());
    for (name, app) in &apps {
        let prefix = app_prefix(app);
        println!(
            "  {name}\t{}\t{}",
            state_of(app, &prefix, false),
            prefix.display()
        );
    }
    0
}

fn main() -> std::process::ExitCode {
    let argv: Vec<String> = std::env::args().skip(1).collect();
    let Some(command) = argv.first().cloned() else {
        print!("{DOC}");
        return std::process::ExitCode::from(1);
    };
    let rest = &argv[1..];
    let code = match command.as_str() {
        "list" => cmd_list(),
        "install" | "sync" => cmd_install(rest),
        "uninstall" => {
            if rest.is_empty() {
                eprintln!("usage: wineapps uninstall APP...");
                2
            } else {
                cmd_uninstall(rest)
            }
        }
        "run" => match rest.split_first() {
            Some((name, tail)) => cmd_run(name, tail),
            None => {
                eprintln!("usage: wineapps run APP [ARGS...]");
                2
            }
        },
        "prefix" => match rest.first() {
            Some(name) => cmd_prefix(name),
            None => {
                eprintln!("usage: wineapps prefix APP");
                2
            }
        },
        "status" => cmd_status(),
        "-h" | "--help" | "help" => {
            print!("{DOC}");
            0
        }
        other => {
            eprintln!("wineapps: unknown command {other}");
            eprint!("{DOC}");
            2
        }
    };
    let _ = std::io::stdout().flush();
    std::process::ExitCode::from(code as u8)
}

const DOC: &str = "\
wineapps — declarative Wine app manager.

Consumes the registry generated by modules/system/wine-apps.nix
(/etc/wineapps/apps.json by default; override with WINEAPPS_REGISTRY) and
manages per-app Wine prefixes under $XDG_DATA_HOME/wineprefixes (default
~/.local/share/wineprefixes; override with WINEPREFIX_BASE).

Commands:
  wineapps list                  show declared apps + install status
  wineapps install [APP...]      ensure apps are installed (no args: all)
  wineapps sync [APP...]         install every declared app that is missing
  wineapps uninstall APP...      remove app prefixes
  wineapps run APP [ARGS...]     launch the app's main executable
  wineapps prefix APP            print the app's prefix directory
  wineapps status                wine/winetricks/prefix overview
";

// -- the small JSON reader the registry needs ---------------------------

mod json {
    //! Objects, arrays, strings, numbers and booleans: exactly what the
    //! generated registry contains.

    #[derive(Debug, Clone, PartialEq)]
    pub enum Value {
        Null,
        Bool(bool),
        Number(f64),
        Str(String),
        Array(Vec<Value>),
        Object(Vec<(String, Value)>),
    }

    impl Value {
        pub fn get(&self, key: &str) -> Option<&Value> {
            match self {
                Value::Object(entries) => entries
                    .iter()
                    .find(|(name, _)| name == key)
                    .map(|(_, value)| value),
                _ => None,
            }
        }

        pub fn as_str(&self) -> Option<&str> {
            match self {
                Value::Str(text) => Some(text),
                _ => None,
            }
        }

        pub fn as_array(&self) -> Option<&[Value]> {
            match self {
                Value::Array(items) => Some(items),
                _ => None,
            }
        }
    }

    pub fn parse(text: &str) -> Option<Value> {
        let chars: Vec<char> = text.chars().collect();
        let mut parser = Parser { chars, pos: 0 };
        let value = parser.value()?;
        parser.skip_ws();
        if parser.pos != parser.chars.len() {
            return None;
        }
        Some(value)
    }

    struct Parser {
        chars: Vec<char>,
        pos: usize,
    }

    impl Parser {
        fn peek(&self) -> Option<char> {
            self.chars.get(self.pos).copied()
        }

        fn skip_ws(&mut self) {
            while matches!(self.peek(), Some(ch) if ch.is_whitespace()) {
                self.pos += 1;
            }
        }

        fn eat(&mut self, ch: char) -> bool {
            if self.peek() == Some(ch) {
                self.pos += 1;
                true
            } else {
                false
            }
        }

        fn value(&mut self) -> Option<Value> {
            self.skip_ws();
            match self.peek()? {
                '{' => self.object(),
                '[' => self.array(),
                '"' => self.string().map(Value::Str),
                't' => self.literal("true", Value::Bool(true)),
                'f' => self.literal("false", Value::Bool(false)),
                'n' => self.literal("null", Value::Null),
                _ => self.number(),
            }
        }

        fn literal(&mut self, text: &str, value: Value) -> Option<Value> {
            for expected in text.chars() {
                if self.peek()? != expected {
                    return None;
                }
                self.pos += 1;
            }
            Some(value)
        }

        fn object(&mut self) -> Option<Value> {
            self.pos += 1;
            let mut entries = Vec::new();
            self.skip_ws();
            if self.eat('}') {
                return Some(Value::Object(entries));
            }
            loop {
                self.skip_ws();
                let key = self.string()?;
                self.skip_ws();
                if !self.eat(':') {
                    return None;
                }
                entries.push((key, self.value()?));
                self.skip_ws();
                if self.eat(',') {
                    continue;
                }
                if self.eat('}') {
                    return Some(Value::Object(entries));
                }
                return None;
            }
        }

        fn array(&mut self) -> Option<Value> {
            self.pos += 1;
            let mut items = Vec::new();
            self.skip_ws();
            if self.eat(']') {
                return Some(Value::Array(items));
            }
            loop {
                items.push(self.value()?);
                self.skip_ws();
                if self.eat(',') {
                    continue;
                }
                if self.eat(']') {
                    return Some(Value::Array(items));
                }
                return None;
            }
        }

        fn string(&mut self) -> Option<String> {
            if !self.eat('"') {
                return None;
            }
            let mut out = String::new();
            loop {
                let ch = self.peek()?;
                self.pos += 1;
                match ch {
                    '"' => return Some(out),
                    '\\' => {
                        let escaped = self.peek()?;
                        self.pos += 1;
                        match escaped {
                            '"' => out.push('"'),
                            '\\' => out.push('\\'),
                            '/' => out.push('/'),
                            'n' => out.push('\n'),
                            't' => out.push('\t'),
                            'r' => out.push('\r'),
                            'u' => {
                                let mut code = String::new();
                                for _ in 0..4 {
                                    code.push(self.peek()?);
                                    self.pos += 1;
                                }
                                let value = u32::from_str_radix(&code, 16).ok()?;
                                out.push(char::from_u32(value).unwrap_or('\u{fffd}'));
                            }
                            _ => return None,
                        }
                    }
                    other => out.push(other),
                }
            }
        }

        fn number(&mut self) -> Option<Value> {
            let start = self.pos;
            if matches!(self.peek(), Some('-')) {
                self.pos += 1;
            }
            while matches!(self.peek(), Some(ch) if ch.is_ascii_digit()) {
                self.pos += 1;
            }
            if matches!(self.peek(), Some('.')) {
                self.pos += 1;
                while matches!(self.peek(), Some(ch) if ch.is_ascii_digit()) {
                    self.pos += 1;
                }
            }
            if self.pos == start {
                return None;
            }
            let text: String = self.chars[start..self.pos].iter().collect();
            text.parse::<f64>().ok().map(Value::Number)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Mutex;

    /// Tests that touch the process environment take turns.
    static ENV_LOCK: Mutex<()> = Mutex::new(());

    fn temp_dir(tag: &str) -> PathBuf {
        let dir = std::env::temp_dir().join(format!(
            "wineapps-{tag}-{}-{}",
            std::process::id(),
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|delta| delta.as_nanos())
                .unwrap_or(0)
        ));
        std::fs::create_dir_all(&dir).expect("temp dir");
        dir
    }

    fn write_script(dir: &Path, name: &str, body: &str) -> PathBuf {
        let path = dir.join(name);
        std::fs::write(&path, format!("#!/bin/sh\n{body}\n")).expect("script");
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let mode = std::fs::metadata(&path).expect("stat").permissions().mode();
            std::fs::set_permissions(&path, std::fs::Permissions::from_mode(mode | 0o111))
                .expect("chmod");
        }
        path
    }

    const REGISTRY: &str = r#"{
      "photoshop": {
        "name": "photoshop",
        "prefix": "photoshop",
        "arch": "win32",
        "executable": "drive_c/Program Files/Photoshop/Photoshop.exe",
        "installer": "https://example.invalid/setup.exe",
        "installArgs": "--mode=silent --dir='C:\\Program Files'",
        "comment": "Adobe Photoshop CS6",
        "winetricks": ["corefonts", "vcrun2019"]
      },
      "shared": {
        "name": "shared",
        "prefix": "common",
        "arch": "win64"
      }
    }"#;

    #[test]
    fn registry_fields_are_read() {
        let dir = temp_dir("registry");
        let path = dir.join("apps.json");
        std::fs::write(&path, REGISTRY).unwrap();
        let apps = load_registry_from(&path).expect("registry");
        assert_eq!(apps.len(), 2);
        let photoshop = &apps["photoshop"];
        assert_eq!(photoshop.prefix, "photoshop");
        assert_eq!(photoshop.arch, "win32");
        assert_eq!(photoshop.comment, "Adobe Photoshop CS6");
        assert_eq!(photoshop.winetricks, vec!["corefonts", "vcrun2019"]);
        assert_eq!(
            photoshop.installer.as_deref(),
            Some("https://example.invalid/setup.exe")
        );
        assert!(apps["shared"].executable.is_none());
        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn missing_registry_is_empty() {
        let dir = temp_dir("empty");
        let apps = load_registry_from(&dir.join("nope.json")).expect("registry");
        assert!(apps.is_empty());
        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn installer_arguments_are_split_like_shlex() {
        assert_eq!(
            install_args("--mode=silent --dir='C:\\Program Files'"),
            vec!["--mode=silent", "--dir=C:\\Program Files"]
        );
        assert!(install_args("").is_empty());
    }

    #[test]
    fn installed_state_follows_the_marker_and_the_executable() {
        let dir = temp_dir("state");
        let prefix = dir.join("p");
        std::fs::create_dir_all(&prefix).unwrap();
        let mut app = App {
            name: "a".into(),
            prefix: "a".into(),
            arch: "win64".into(),
            executable: Some("drive_c/a.exe".into()),
            ..App::default()
        };
        assert!(!is_installed(
            &app,
            &prefix,
            resolve_exe(&app, &prefix).as_deref()
        ));
        std::fs::write(prefix.join(".wineapps-installed"), "a\n").unwrap();
        assert!(is_installed(
            &app,
            &prefix,
            resolve_exe(&app, &prefix).as_deref()
        ));
        std::fs::remove_file(prefix.join(".wineapps-installed")).unwrap();
        app.executable = None;
        assert!(!is_installed(&app, &prefix, None));
        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn prefix_root_prefers_wineprefix_base_then_xdg() {
        let _guard = ENV_LOCK.lock().unwrap();
        let dir = temp_dir("root");
        std::env::set_var("WINEPREFIX_BASE", dir.join("bases"));
        assert_eq!(prefix_root(), dir.join("bases"));
        std::env::remove_var("WINEPREFIX_BASE");
        std::env::set_var("XDG_DATA_HOME", dir.join("data"));
        assert_eq!(prefix_root(), dir.join("data").join("wineprefixes"));
        std::env::remove_var("XDG_DATA_HOME");
        std::fs::remove_dir_all(&dir).ok();
    }

    /// The install path end to end: stub wine binaries in a temp dir, a local
    /// installer, and the marker file at the end.
    #[test]
    fn install_runs_wineboot_winetricks_and_the_installer() {
        let _guard = ENV_LOCK.lock().unwrap();
        let dir = temp_dir("install");
        let log = dir.join("calls.log");
        let tools = dir.join("bin");
        std::fs::create_dir_all(&tools).unwrap();
        let log_arg = log.display().to_string();
        for tool in ["wineboot", "wine", "wineserver"] {
            write_script(
                &tools,
                tool,
                &format!("echo \"{tool} $*\" >> {log_arg}\n[ \"$1\" = \"-w\" ] && exit 0\nexit 0"),
            );
        }
        write_script(
            &tools,
            "winetricks",
            &format!("echo \"winetricks $*\" >> {log_arg}\nexit 0"),
        );
        let installer = dir.join("setup.exe");
        std::fs::write(&installer, b"stub").unwrap();
        let registry = dir.join("apps.json");
        std::fs::write(
            &registry,
            format!(
                r#"{{"app": {{"name": "app", "prefix": "app", "arch": "win64",
                    "installer": "{}", "installArgs": "--silent",
                    "winetricks": ["corefonts"]}}}}"#,
                installer.display()
            ),
        )
        .unwrap();

        std::env::set_var("WINEAPPS_REGISTRY", &registry);
        std::env::set_var("WINEPREFIX_BASE", dir.join("prefixes"));
        std::env::set_var("WINEBOOT", tools.join("wineboot").display().to_string());
        std::env::set_var("WINE", tools.join("wine").display().to_string());
        std::env::set_var("WINESERVER", tools.join("wineserver").display().to_string());
        std::env::set_var("WINETRICKS", tools.join("winetricks").display().to_string());

        let apps = load_registry().expect("registry");
        assert!(install_one(&apps["app"]));
        let calls = std::fs::read_to_string(&log).unwrap();
        assert!(calls.contains("wineboot -u"), "{calls}");
        assert!(calls.contains("winetricks -q corefonts"), "{calls}");
        assert!(
            calls.contains(&format!("wine {}", installer.display())),
            "{calls}"
        );
        assert!(calls.contains("--silent"), "{calls}");
        assert!(dir
            .join("prefixes")
            .join("app")
            .join(".wineapps-installed")
            .exists());
        // A second run reports the marker instead of reinstalling.
        let before = std::fs::read_to_string(&log).unwrap();
        assert!(install_one(&apps["app"]));
        assert_eq!(std::fs::read_to_string(&log).unwrap(), before);

        for name in [
            "WINEAPPS_REGISTRY",
            "WINEPREFIX_BASE",
            "WINEBOOT",
            "WINE",
            "WINESERVER",
            "WINETRICKS",
        ] {
            std::env::remove_var(name);
        }
        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn uninstall_and_prefix_go_through_the_registry() {
        let _guard = ENV_LOCK.lock().unwrap();
        let dir = temp_dir("uninstall");
        let registry = dir.join("apps.json");
        std::fs::write(&registry, REGISTRY).unwrap();
        std::env::set_var("WINEAPPS_REGISTRY", &registry);
        std::env::set_var("WINEPREFIX_BASE", dir.join("prefixes"));
        std::fs::create_dir_all(dir.join("prefixes").join("photoshop")).unwrap();

        assert_eq!(cmd_prefix("photoshop"), 0);
        // "shared" points at the "common" prefix, so removal must be refused.
        std::fs::create_dir_all(dir.join("prefixes").join("common")).unwrap();
        assert_eq!(cmd_uninstall(&["shared".to_string()]), 1);
        assert!(dir.join("prefixes").join("common").exists());
        assert_eq!(cmd_uninstall(&["photoshop".to_string()]), 0);
        assert!(!dir.join("prefixes").join("photoshop").exists());
        assert_eq!(cmd_uninstall(&["nope".to_string()]), 1);

        std::env::remove_var("WINEAPPS_REGISTRY");
        std::env::remove_var("WINEPREFIX_BASE");
        std::fs::remove_dir_all(&dir).ok();
    }

    #[test]
    fn list_reports_the_declared_state() {
        let _guard = ENV_LOCK.lock().unwrap();
        let dir = temp_dir("list");
        let registry = dir.join("apps.json");
        std::fs::write(&registry, REGISTRY).unwrap();
        std::env::set_var("WINEAPPS_REGISTRY", &registry);
        std::env::set_var("WINEPREFIX_BASE", dir.join("prefixes"));
        std::fs::create_dir_all(dir.join("prefixes").join("photoshop")).unwrap();
        std::fs::write(
            dir.join("prefixes")
                .join("photoshop")
                .join(".wineapps-installed"),
            "photoshop\n",
        )
        .unwrap();
        assert_eq!(cmd_list(), 0);
        std::env::remove_var("WINEAPPS_REGISTRY");
        std::env::remove_var("WINEPREFIX_BASE");
        std::fs::remove_dir_all(&dir).ok();
    }
}
